INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('ba502608-a6c4-4136-a78c-2a21e5016688', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-AUD-1001', 'Aviator Headphones — Onyx', 'aviator-headphones-onyx', 'Over-ear headphones with 40 hours of playback and a travel case that actually fits in a backpack pocket.', 'The Aviator is tuned flat out of the box, no bass boost hiding behind an EQ preset. Memory-foam ear cushions and a stainless steel headband slider mean they stay comfortable past the three-hour mark, which is where most over-ear headphones start to hurt.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('f476469d-0119-4ac1-ad76-377d9fbd9352', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-AUD-1002', 'Pulse True Wireless Earbuds', 'pulse-earbuds-case', 'Compact earbuds with active noise cancellation and a case that charges wirelessly.', 'Pulse earbuds seal well enough to cancel a plane cabin without turning up the volume to compensate. Each bud is rated IPX4, so a sweaty run or a walk in the rain won''t end the relationship.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('ce4114b0-9f7d-4d4b-8b90-d9cfa99bad93', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-AUD-1003', 'Basecamp Smart Speaker', 'basecamp-smart-speaker', 'Room-filling sound from a speaker small enough to leave on a kitchen counter.', 'A 3-inch woofer and dual tweeters give the Basecamp speaker more low end than its size suggests, without the boom that makes small speakers sound cheap at higher volumes.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('76961349-420d-4ae5-aa81-ff8de96f4c19', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1004', 'Keystroke Mechanical Keyboard', 'keystroke-mechanical-keyboard', 'A tenkeyless mechanical keyboard with hot-swappable switches, so you can change the feel without a soldering iron.', 'Keystroke ships with tactile brown switches installed, but the hot-swap sockets accept any standard 3-pin or 5-pin switch if you decide six months from now that you want something louder, or quieter.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('669fac92-9684-4d0f-877c-b4d07f849acc', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1005', 'Glide Wireless Mouse', 'glide-wireless-mouse', 'An ergonomic wireless mouse with a 4,000 DPI sensor and a scroll wheel that free-spins on demand.', 'Glide''s shape was built around a hand-tracing study, not a mood board — the thumb rest sits where thumbs actually rest. A side switch flips the scroll wheel between clicked steps and a fast free-spin for long documents.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('8d17594b-1496-4d4d-a046-3957a7a54d46', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1006', 'Hubline 7-in-1 USB-C Hub', 'hubline-usb-c-hub', 'Seven ports, one cable — HDMI, USB-A, SD, and 100W pass-through charging from a single USB-C connection.', 'Hubline turns one USB-C port into a 4K/60Hz HDMI output, two USB-A 3.0 ports, an SD/microSD reader, and a 100W pass-through so your laptop still charges while everything else is plugged in.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('82d88e6a-a062-4de8-b552-7f62cc9c867e', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1007', 'Arclight LED Desk Lamp', 'arclight-desk-lamp', 'An articulated LED lamp with adjustable color temperature and a built-in USB-C charging port.', 'Arclight''s arm holds any angle without drifting, which sounds like a low bar until you''ve owned a lamp that doesn''t. Five brightness levels and three color temperatures cover everything from late-night reading to on-camera lighting.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('2caed370-aae2-408b-a362-3500638901be', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1008', 'Orbit 1080p Webcam', 'orbit-webcam-clip', 'A 1080p webcam with a wide-angle lens and a privacy shutter that actually stays shut.', 'Orbit''s autofocus keeps up with normal fidgeting, and the low-light correction means you don''t look like you''re calling from a cave once the sun goes down.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('e34dba9d-06ef-40ce-a611-01496df7199b', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1009', 'Anchor 3-in-1 Charging Dock', 'anchor-charging-dock', 'Charges phone, watch and earbuds at once, angled so you can still see notifications.', 'Anchor holds a phone at an angle that keeps Face ID and notifications visible while it charges, with a dedicated puck for a smartwatch and a slot underneath for an earbuds case.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('69d34977-d7a6-4ed4-8de1-4a115c58832a', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-PWR-1010', 'Voltpack 20,000mAh Power Bank', 'voltpack-power-bank', 'Enough capacity for four full phone charges, with pass-through so it charges itself and your laptop at the same time.', 'Voltpack''s 20,000mAh cell is enough to take a phone from empty to full about four times, or top off a laptop once with enough left over for a phone.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('28fe8400-089a-4531-b360-e618e5d6499d', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-PWR-1011', 'Driftcase 1TB Portable SSD', 'driftcase-portable-ssd', 'A 1TB solid-state drive rated to survive a 2-meter drop, with transfer speeds fast enough for 4K video editing.', 'Driftcase reads at up to 1,050MB/s, fast enough to edit 4K footage directly off the drive instead of copying it over first. The aluminum shell is rated for a 2-meter drop onto a hard surface.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('fb93a0a9-ae04-4a13-9718-607806deb624', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-WBL-1012', 'Pulse Smartwatch', 'pulse-smartwatch', 'A smartwatch with a seven-day battery, GPS, and a screen bright enough to read in direct sun.', 'Pulse tracks heart rate, sleep and about thirty workout types, and holds a charge for a full week between charges — the display stays on the whole time, not just on wrist-raise.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('b37381d9-e112-48ee-97a2-a4a902aed7d3', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-CND-2004', 'Amber Fields Soy Candle', 'amber-fields-candle', 'A single-wick soy candle in amber, cedar and a little black pepper. Burns about 45 hours.', 'Amber Fields is our best-selling scent for a reason — warm without being sweet, and it doesn''t turn cloying halfway through the jar the way a lot of amber candles do.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('6ba888e9-1898-4b3f-8e31-2ea2a06c4ba8', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-CND-2005', 'Orchard Candle Trio', 'orchard-candle-trio', 'Three 4oz candles — apple, fig and spiced pear — sized for testing scents before committing to a full jar.', 'The Orchard trio is how most people find their favorite Fernwood scent. Each jar is a quarter of our standard size, enough for about 15 hours of burn time, which is plenty to decide whether fig belongs on your shelf permanently.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('06030db2-5fb0-4026-a59b-77f4637dbf5f', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-POT-2001', 'Hearth Ceramic Mug', 'hearth-ceramic-mug', 'A 12oz stoneware mug, thrown and glazed by hand — no two exactly alike.', 'Each Hearth mug starts as a lump of stoneware clay on Priya''s wheel and comes off it twenty minutes later shaped, though not yet fired. The reactive glaze runs differently every time it hits the kiln, so the mug you get is the only one exactly like it.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('1e0c0fe3-436e-4121-9669-c4a22cd86563', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-POT-2002', 'Bud Ceramic Vase', 'bud-ceramic-vase', 'A single-stem bud vase in a hand-mixed matte glaze, tall enough for a branch, small enough for a windowsill.', 'Bud vases are thrown one at a time on a slow wheel, which is why we can only make about fifteen a week. The narrow neck holds a single stem upright without the vase tipping, which is harder to get right than it sounds.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('a2ae357d-f371-43fa-ba74-9a6c10f44ff0', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-POT-2003', 'Nested Ceramic Bowl Set (3)', 'nested-ceramic-bowls', 'Three stoneware bowls in graduated sizes that nest for storage and stack for the shelf.', 'This set covers cereal, soup and serving in one glaze run, so the three bowls actually match instead of being assembled from different batches after the fact.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('d1d1e607-8b48-44ce-b7af-e240ea90d4db', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2006', 'Harvest Woven Tote', 'harvest-woven-tote', 'A market tote hand-loomed from cotton and jute, sturdy enough for actual groceries.', 'This isn''t a decorative tote — the jute base and cotton weave are rated to carry real weight, and we''ve tested it with two full grocery bags'' worth without the seams complaining.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('a916edbf-2887-455a-bea2-05150c016965', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2007', 'Cabin Wool Throw', 'cabin-wool-throw', 'A 50x60 lambswool throw, woven on a floor loom in a three-color stripe pattern.', 'Cabin is woven from lambswool on a floor loom, in three colorways that rotate with the seasons. It''s substantial — closer to a blanket than a scarf-weight throw — and holds up to years of actual couch use.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('f6b542c4-c82b-4647-bf10-72cb71cfa862', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2008', 'Market Linen Apron', 'market-linen-apron', 'A cross-back linen apron with one deep pocket, cut generously enough to actually protect your clothes.', 'The cross-back straps mean this apron stays put without a neck loop cutting into you after an hour of standing at the counter. Heavyweight linen softens with every wash instead of wearing thin.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('d2fac965-4fb5-4a81-969c-faf551e4d008', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2009', 'Driftwood Macrame Hanging', 'driftwood-macrame-hanging', 'A knotted cotton-cord wall hanging on a foraged driftwood dowel, about 22 inches long.', 'Each dowel is foraged, not milled, so the wood grain and curve are different on every piece — you''re choosing a specific dowel, not a style number.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('d3be3d61-3d6c-4a9e-856b-5d83106b7789', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-WD-2010', 'Maple End-Grain Cutting Board', 'maple-cutting-board', 'An end-grain maple board that''s easier on knife edges than a face-grain board twice its price.', 'End-grain construction means the wood fibers face up, so a knife edge slides between them instead of across them — it''s genuinely easier on your knives, not just a marketing distinction.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('92b3ed28-2ed0-4428-802f-fd716e0d98b9', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-WD-2011', 'Fieldnote Leather Journal', 'fieldnote-leather-journal', 'A refillable leather journal with 160 pages of Italian paper and a brass closure.', 'The vegetable-tanned cover develops a patina with handling — the one on the shelf sample looks nothing like the one that shipped a year ago, and that''s the point.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('b80a7ae3-4103-40cb-8936-a26df7666b56', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-WD-2012', 'Birchwood Spoon Set (3)', 'birchwood-spoon-set', 'Three hand-carved birchwood cooking spoons in different profiles — stirring, serving, and a slotted spoon.', 'Each spoon is carved from a single piece of birch, no glued laminations to eventually split. The slotted spoon''s holes are burned through, not drilled, which leaves a smoother edge against a pan.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('a36e8fa4-f216-464c-b615-7398a362d802', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-ACC-3012', 'Thresh Doorway Pull-Up Bar', 'thresh-pull-up-bar', 'A no-screw doorway pull-up bar rated for 300 lbs, that comes down in ten seconds when you''re done.', 'Thresh wedges into a standard doorframe using leverage, not screws, so it comes down in ten seconds and doesn''t leave holes in a rental apartment''s trim.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('7c9285d5-ac67-4ae4-9db7-fb5875832c15', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-CDO-3005', 'Tracline Yoga Mat', 'tracline-yoga-mat', 'A 5mm natural rubber mat with a textured surface that actually grips through a sweaty flow.', 'Most yoga mats get slippery right when you need grip most — twenty minutes into a hot flow. Tracline''s natural rubber base and textured top layer are built specifically to hold traction as you sweat, not despite it.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('230bda7f-bfaf-4342-abb6-2269a1d85a04', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-CDO-3006', 'Speedcoil Jump Rope', 'speedcoil-jump-rope', 'A ball-bearing speed rope with a steel cable core, adjustable to any height without cutting the cord.', 'Ball bearings in each handle let the cable spin independently of your grip, which is the difference between a rope that keeps up with double-unders and one that doesn''t.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('806a0397-4de5-477b-b74a-0728401a0a59', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-CDO-3007', 'Corestrike Textured Foam Roller', 'corestrike-foam-roller', 'A high-density foam roller with a textured surface that mimics a deep-tissue massage.', 'The textured ridges apply more targeted pressure than a smooth roller, closer to what a foam-roller skeptic expects a massage therapist''s thumbs to feel like.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('49aa1075-7ccb-442f-8783-a7cf7137d74a', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-CDO-3008', 'Looplevel Resistance Band Set', 'looplevel-resistance-bands', 'Three fabric resistance loop bands — light, medium, heavy — that don''t roll or snap the way rubber bands do.', 'Fabric bands grip the skin instead of rolling up mid-set, and they don''t develop the small tears that eventually make rubber loop bands snap without warning.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('c1e2153b-151f-4cd1-b94c-269e1498dc7b', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-HYD-3009', 'Summit Insulated Water Bottle', 'summit-water-bottle', 'A 32oz insulated bottle that keeps water cold for 24 hours, even left in a hot car.', 'Double-wall vacuum insulation keeps water cold for 24 hours and hot drinks warm for 12, tested in an actual closed car in July, not just a lab spec sheet.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('9a78c18b-a4e7-48cc-963f-7cc9d81f912b', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-HYD-3010', 'Shakerline Protein Shaker', 'shakerline-protein-shaker', 'A 24oz shaker bottle with a wire whisk ball that actually breaks up protein powder clumps.', 'The stainless wire whisk ball does the job a lot of shaker bottles claim to do with just ridges molded into the plastic — no clumps left at the bottom after one shake.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('01ad890b-b433-4eee-b17b-0bc1d2314187', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-HYD-3011', 'Trailhead Gym Duffel', 'trailhead-duffel-bag', 'A 40L duffel with a separate vented shoe compartment, so gym clothes don''t end up smelling like gym shoes.', 'The bottom compartment is vented and separate from the main pack, built specifically to keep sweaty shoes from turning the rest of the bag into a problem by the time you get home.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('bdc42fb1-b864-48e1-b715-148aa5134e39', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-STR-3001', 'Ironline Adjustable Dumbbell (Pair)', 'ironline-adjustable-dumbbell', 'A pair of dumbbells that adjust from 10 to 50 lbs each in 5-lb increments, replacing a full rack.', 'Twist the dial, lift, and the plates you don''t need stay in the tray — no separate weight plates to lose track of, and no rack taking up a corner of the room.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('73c50878-a6aa-48f3-acc4-55fcd57cf405', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-STR-3002', 'Anchor Cast-Iron Kettlebell', 'anchor-kettlebell', 'A single-cast kettlebell with a wide, flat base and a handle wide enough for a two-handed grip.', 'Cast in one piece — no seam to catch a callus on — with a powder-coat finish that holds up to being dropped on concrete, which kettlebells eventually are.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('54e6e008-cb88-4e36-b9d3-81dd687743b1', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-STR-3003', 'Ironline Adjustable Bench', 'bench-press-incline-bench', 'A flat-to-incline bench rated for 600 lbs, with seven back positions and a stable footprint.', 'Seven back positions go from flat to an 85-degree incline, with a pin-and-pop adjustment that doesn''t loosen over months of use the way some cheaper hinge mechanisms do.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, variant_count) VALUES ('0a092b09-8af1-46d8-a139-d4f56fc50d03', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-STR-3004', 'Tempo Ankle Weights (Pair)', 'tempo-ankle-weights', 'Adjustable ankle weights from 1 to 5 lbs each, for slowing down bodyweight work on purpose.', 'Five removable 1-lb sandbags per weight mean you can dial in exactly how much resistance to add to leg raises, donkey kicks or a slow walk, instead of committing to a fixed weight.
